import{_ as r,o,c as a,a3 as n}from"./chunks/framework.DMtjdCb-.js";const e="/help/assets/release-radar.ja.DDrOVrXL.png",s="/help/assets/resource-variants.ja.DkzYVyE7.png",i="/help/assets/torrent-results.ja.DkDZ5bsa.png",m=JSON.parse('{"title":"4. 購読とダウンロード","description":"","frontmatter":{},"headers":[],"relativePath":"ja/subscribe.md","filePath":"ja/subscribe.md"}'),l={name:"ja/subscribe.md"};function g(d,t,h,p,c,b){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="_4-購読とダウンロード" tabindex="-1">4. 購読とダウンロード <a class="header-anchor" href="#_4-購読とダウンロード" aria-label="Permalink to &quot;4. 購読とダウンロード&quot;">​</a></h1><p>リリースを選び、購読やダウンロードを開始する手順を説明します。Ani-RSS の購読は以降の配信も追跡し、Torrent は今回選んだリリースをダウンロードします。</p><h2 id="作品を探す" tabindex="-1">作品を探す <a class="header-anchor" href="#作品を探す" aria-label="Permalink to &quot;作品を探す&quot;">​</a></h2><ol><li>ホームの <strong>タイトル・別名</strong> で検索するか、<strong>新作レーダー</strong> を開きます。</li><li>レーダーでは対象シーズンを選び、作品名から詳細を開きます。</li><li><strong>Ani-RSS</strong> の結果を確認し、更新が必要な場合はリソースを検索します。</li></ol><p><img src="'+e+'" alt="新作レーダー：シーズンごとの作品と更新を確認" loading="lazy"></p><p><strong>同期</strong> は Ani-RSS が把握している購読・メディア状態を取得します。<strong>検索</strong> は対象シーズンの作品を順番に調べます。バックグラウンドで進み、画面に進捗が表示されます。</p><h2 id="ani-rss-の配信版を選ぶ" tabindex="-1">Ani-RSS の配信版を選ぶ <a class="header-anchor" href="#ani-rss-の配信版を選ぶ" aria-label="Permalink to &quot;Ani-RSS の配信版を選ぶ&quot;">​</a></h2><ol><li>リリースグループを選びます。</li><li>同じグループに複数の版がある場合は、プルダウンで字幕、配信元、画質を確認します。簡体字・繁体字、Baha などもここで区別します。</li><li>希望のリソースを選び、<strong>購読を有効化</strong> を押します。確認画面でグループと版を確認し、もう一度 <strong>購読を有効化</strong> を押します。</li><li><strong>購読中</strong> になったら、取得済みの話数を作品の再生欄で確認します。</li></ol><p><img src="'+s+'" alt="グループ選択後に字幕・配信元・画質を選ぶ" loading="lazy"></p><p><strong>確認する状態：</strong> 購読中と表示され、取得した動画が再生欄に並びます。以降の配信は Ani-RSS が取得し、AnimeMachine に状態が同期されます。</p><p>言語や画質の不一致表示は、現在の優先条件によるものです。その版を使用する場合は強制購読を選び、確認画面で不一致の項目を確認できます。</p><h2 id="放送前の作品や保存用リリースを追跡する" tabindex="-1">放送前の作品や保存用リリースを追跡する <a class="header-anchor" href="#放送前の作品や保存用リリースを追跡する" aria-label="Permalink to &quot;放送前の作品や保存用リリースを追跡する&quot;">​</a></h2><p>作品詳細の <strong>リリース追跡</strong> を開き、<strong>配信開始時に購読</strong> を選ぶと、<strong>リリース待ち</strong> として保存されます。定期検索で条件に合う配信版が見つかると、Ani-RSS の購読を開始します。未接続の間も設定は保持されます。</p><p>標準では設定のリリースグループを使用します。さらに限定する場合はそのチェックを外し、グループを展開して、例えば <strong>Kirara Fantasia → Baha</strong> だけを選びます。既存の Ani-RSS 購読の設定は保持されます。</p><p>BDRip などの保存用リリースには <strong>アーカイブ向けリリースを追跡</strong> を使います。見つかった時点では通知のみで、確認後にダウンロードを選択できます。新作レーダーの <strong>リリース追跡</strong> から、一覧の確認・変更・停止ができます。</p><h2 id="torrent-を選ぶ" tabindex="-1">Torrent を選ぶ <a class="header-anchor" href="#torrent-を選ぶ" aria-label="Permalink to &quot;Torrent を選ぶ&quot;">​</a></h2><ol><li><strong>設定 → 接続</strong> で qBittorrent が利用可能か確認します。</li><li>作品詳細で <strong>Torrent を検索</strong> し、検索完了を待ちます。</li><li><strong>Torrent</strong> の結果を展開し、グループと字幕・画質の版を選びます。</li><li><strong>ダウンロード計画を確認</strong> で作品、ファイル、保存先を確認して送信します。</li><li>qBittorrent を開き、追加された停止中のタスクを選んでダウンロードを開始します。</li></ol><p><img src="'+i+'" alt="Torrent の結果を展開し、グループと版を選ぶ" loading="lazy"></p><p>ローカル Torrent の計画は停止状態で追加され、タスクを開始すると転送が始まります。放送中の作品はシーズンと話数の連続性を確認します。完結作品や映画もコレクションの補完に利用できます。</p><p>数百話に及ぶ連載作品は、各バージョンの直近 24 話が連続してそろっているか確認し、最新から 1 話までの遅れを許容します。一度の検索で全話をそろえる必要はありません。保存用の版では、過去の話を分けて収集できます。</p><h2 id="手持ちの-torrent-プールを使う" tabindex="-1">手持ちの Torrent プールを使う <a class="header-anchor" href="#手持ちの-torrent-プールを使う" aria-label="Permalink to &quot;手持ちの Torrent プールを使う&quot;">​</a></h2><p><strong>設定 → 接続 → Torrent Collector</strong> では、作品検索とプールを別々に利用できます。</p><table tabindex="0"><thead><tr><th>使い方</th><th>設定</th></tr></thead><tbody><tr><td>作品ごとに探す</td><td>詳細で <strong>Torrent を検索</strong>。別途 Collector を起動する必要はありません</td></tr><tr><td>手持ちの <code>.torrent</code> フォルダーを使う</td><td><strong>Torrent プールのパス</strong> を指定し、<strong>プールを定期スキャン</strong> を有効にします</td></tr><tr><td>プールへ自動収集する</td><td>Compose で Torrent Collector を導入し、<strong>Torrent を自動収集</strong> を有効にします</td></tr></tbody></table><p>手持ちのプールだけを使う場合は、自動収集を無効にし、定期スキャンを残せます。どの方法でも同じリリース設定を使い、作品詳細から選択します。ファイル一覧と保存先を確認してからダウンロード計画を送信します。</p><h2 id="ダウンロードが始まらない" tabindex="-1">ダウンロードが始まらない <a class="header-anchor" href="#ダウンロードが始まらない" aria-label="Permalink to &quot;ダウンロードが始まらない&quot;">​</a></h2><p>AnimeMachine の接続とタスク状態を確認し、qBittorrent でタスクや接続可能なシーダーを確認します。送信済みでピアを待っている状態と、まだ計画を送信していない状態を区別します。<a href="./troubleshooting.html#download">確認手順</a>も参照してください。</p>',26)])])}const u=r(l,[["render",g]]);export{m as __pageData,u as default};
